namespace sv_98704dec3a9f450a98c618ec9cecdf9b.Models;

public record JobApplication(PersonalInfo Personal, WorkHistory Work, List<Reference> References, string CoverLetter);
public record PersonalInfo(string FullName, string Email, string Phone, string Address);
public record WorkHistory(List<WorkEntry> Entries);
public record WorkEntry(string Company, string Title, DateTime StartDate, DateTime? EndDate, string Description);
public record Reference(string Name, string Relationship, string Email, string Phone);

public interface IApplicationService
{
    Task<int> SubmitApplicationAsync(JobApplication application);
    Task<bool> ValidateEmailAsync(string email);
}

@page "/apply"
@using sv_98704dec3a9f450a98c618ec9cecdf9b.Models
@using sv_98704dec3a9f450a98c618ec9cecdf9b.Components.Pages.Apply
@rendermode InteractiveServer
@inject IApplicationService ApplicationService

<PageTitle>Job Application</PageTitle>

<div class="apply-page">
    <h1>Job Application</h1>

    <StepIndicator CurrentStep="@currentStep"
                   CompletedSteps="@completedSteps"
                   OnStepClicked="GoToStep" />

    @switch (currentStep)
    {
        case 0:
            <PersonalInfoStep FullName="@personalInfo.FullName"
                              Email="@personalInfo.Email"
                              Phone="@personalInfo.Phone"
                              Address="@personalInfo.Address"
                              ValidateEmail="ApplicationService.ValidateEmailAsync"
                              OnNext="HandlePersonalInfoNext" />
            break;
        case 1:
            <WorkHistoryStep Entries="@workEntries"
                             OnNext="HandleWorkHistoryNext"
                             OnBack="GoBack" />
            break;
        case 2:
            <ReferencesStep References="@references"
                            OnNext="HandleReferencesNext"
                            OnBack="GoBack" />
            break;
        case 3:
            <CoverLetterStep CoverLetter="@coverLetter"
                             OnNext="HandleCoverLetterNext"
                             OnBack="GoBack" />
            break;
        case 4:
            <ReviewStep Personal="@reviewPersonal"
                        WorkEntries="@workEntries"
                        References="@references"
                        CoverLetter="@coverLetter"
                        OnEdit="GoToStep"
                        OnBack="GoBack"
                        OnSubmit="HandleSubmit"
                        IsSubmitting="@isSubmitting"
                        IsSubmitted="@isSubmitted"
                        ApplicationId="@applicationId"
                        ErrorMessage="@submitError" />
            break;
    }
</div>

@code {
    private int currentStep;
    private HashSet<int> completedSteps = new();

    // Step 1 state
    private PersonalInfoStep.PersonalInfoResult personalInfo = new("", "", "", "");

    // Step 2 state
    private List<WorkEntryForm.WorkEntryModel> workEntries = new()
    {
        new WorkEntryForm.WorkEntryModel("", "", DateTime.Today, null, "", false)
    };

    // Step 3 state
    private List<ReferenceForm.ReferenceModel> references = new()
    {
        new ReferenceForm.ReferenceModel("", "", "", ""),
        new ReferenceForm.ReferenceModel("", "", "", "")
    };

    // Step 4 state
    private string coverLetter = "";

    // Step 5 state
    private bool isSubmitting;
    private bool isSubmitted;
    private int applicationId;
    private string? submitError;

    private PersonalInfoStep.PersonalInfoResult reviewPersonal => personalInfo;

    private void GoToStep(int step)
    {
        if (step <= currentStep || completedSteps.Contains(step))
        {
            currentStep = step;
        }
    }

    private void GoBack()
    {
        if (currentStep > 0)
        {
            currentStep--;
        }
    }

    private void HandlePersonalInfoNext(PersonalInfoStep.PersonalInfoResult result)
    {
        personalInfo = result;
        completedSteps.Add(0);
        currentStep = 1;
    }

    private void HandleWorkHistoryNext(List<WorkEntryForm.WorkEntryModel> entries)
    {
        workEntries = entries;
        completedSteps.Add(1);
        currentStep = 2;
    }

    private void HandleReferencesNext(List<ReferenceForm.ReferenceModel> refs)
    {
        references = refs;
        completedSteps.Add(2);
        currentStep = 3;
    }

    private void HandleCoverLetterNext(string letter)
    {
        coverLetter = letter;
        completedSteps.Add(3);
        currentStep = 4;
    }

    private async Task HandleSubmit()
    {
        isSubmitting = true;
        submitError = null;

        try
        {
            var workHistory = new WorkHistory(
                workEntries.Select(e => new WorkEntry(e.Company, e.Title, e.StartDate, e.EndDate, e.Description)).ToList()
            );
            var referenceList = references.Select(r => new Reference(r.Name, r.Relationship, r.Email, r.Phone)).ToList();
            var personal = new PersonalInfo(personalInfo.FullName, personalInfo.Email, personalInfo.Phone, personalInfo.Address);

            var application = new JobApplication(personal, workHistory, referenceList, coverLetter);
            applicationId = await ApplicationService.SubmitApplicationAsync(application);
            isSubmitted = true;
            completedSteps.Add(4);
        }
        catch (Exception ex)
        {
            submitError = $"Submission failed: {ex.Message}";
        }
        finally
        {
            isSubmitting = false;
        }
    }
}

.apply-page {
    max-width: 800px;
    margin: 0 auto;
    padding: 2rem;
}

/* Step Indicator */
.step-indicator {
    display: flex;
    align-items: center;
    justify-content: center;
    margin-bottom: 2rem;
    flex-wrap: wrap;
    gap: 0.25rem;
}

.step {
    display: flex;
    flex-direction: column;
    align-items: center;
    background: none;
    border: none;
    cursor: pointer;
    padding: 0.5rem;
    min-width: 80px;
}

.step:disabled {
    cursor: not-allowed;
}

.step__number {
    width: 36px;
    height: 36px;
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
    font-weight: bold;
    font-size: 0.9rem;
    border: 2px solid #ccc;
    background: white;
    color: #999;
    margin-bottom: 0.25rem;
}

.step--current .step__number {
    border-color: #0066cc;
    background: #0066cc;
    color: white;
}

.step--completed .step__number {
    border-color: #28a745;
    background: #28a745;
    color: white;
}

.step__check {
    font-size: 1rem;
}

.step__label {
    font-size: 0.75rem;
    color: #666;
    text-align: center;
}

.step--current .step__label {
    color: #0066cc;
    font-weight: 600;
}

.step--completed .step__label {
    color: #28a745;
}

.step--future .step__label {
    color: #999;
}

.step__connector {
    width: 30px;
    height: 2px;
    background: #ccc;
    align-self: center;
    margin-bottom: 1rem;
}

.step__connector--completed {
    background: #28a745;
}

/* Step Content */
.step-content {
    background: white;
    border: 1px solid #e0e0e0;
    border-radius: 8px;
    padding: 2rem;
}

.step-content h2 {
    margin-top: 0;
    margin-bottom: 1.5rem;
    color: #333;
}

.step-description {
    color: #666;
    margin-bottom: 1rem;
}

/* Form Elements */
.form-group {
    margin-bottom: 1rem;
}

.form-group label {
    display: block;
    font-weight: 500;
    margin-bottom: 0.25rem;
    color: #444;
}

.form-group--checkbox label {
    display: inline-flex;
    align-items: center;
    gap: 0.5rem;
    font-weight: normal;
}

.form-control {
    width: 100%;
    padding: 0.5rem 0.75rem;
    border: 1px solid #ccc;
    border-radius: 4px;
    font-size: 1rem;
    box-sizing: border-box;
}

.form-control:focus {
    outline: none;
    border-color: #0066cc;
    box-shadow: 0 0 0 2px rgba(0, 102, 204, 0.2);
}

.form-control:disabled {
    background: #f5f5f5;
    color: #999;
}

.form-row {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 1rem;
}

/* Work Entry & Reference Fieldsets */
.work-entry,
.reference-entry {
    border: 1px solid #e0e0e0;
    border-radius: 6px;
    padding: 1.5rem;
    margin-bottom: 1rem;
}

.work-entry legend,
.reference-entry legend {
    font-weight: 600;
    color: #555;
    padding: 0 0.5rem;
}

/* Buttons */
.btn {
    padding: 0.6rem 1.2rem;
    border: none;
    border-radius: 4px;
    font-size: 1rem;
    cursor: pointer;
    font-weight: 500;
    transition: background-color 0.2s;
}

.btn:disabled {
    opacity: 0.6;
    cursor: not-allowed;
}

.btn-primary {
    background: #0066cc;
    color: white;
}

.btn-primary:hover:not(:disabled) {
    background: #0052a3;
}

.btn-outline {
    background: white;
    border: 1px solid #ccc;
    color: #333;
}

.btn-outline:hover:not(:disabled) {
    background: #f5f5f5;
}

.btn-secondary {
    background: #f0f0f0;
    color: #333;
    border: 1px dashed #aaa;
}

.btn-secondary:hover:not(:disabled) {
    background: #e0e0e0;
}

.btn-danger {
    background: #dc3545;
    color: white;
}

.btn-danger:hover:not(:disabled) {
    background: #c82333;
}

.btn-sm {
    padding: 0.3rem 0.8rem;
    font-size: 0.85rem;
}

.btn-link {
    background: none;
    border: none;
    color: #0066cc;
    cursor: pointer;
    font-size: 0.9rem;
    text-decoration: underline;
    padding: 0;
}

.btn-link:hover {
    color: #004499;
}

.btn-submit {
    padding: 0.75rem 2rem;
    font-size: 1.1rem;
}

/* Step Actions */
.step-actions {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-top: 2rem;
    padding-top: 1rem;
    border-top: 1px solid #eee;
}

/* Error Message */
.error-message {
    background: #fff3f3;
    border: 1px solid #ffcccc;
    color: #cc0000;
    padding: 0.75rem 1rem;
    border-radius: 4px;
    margin-top: 1rem;
}

/* Cover Letter */
.cover-letter-input {
    resize: vertical;
    min-height: 200px;
}

.character-count {
    display: block;
    text-align: right;
    font-size: 0.85rem;
    color: #666;
    margin-top: 0.25rem;
}

/* Review Step */
.review-section {
    margin-bottom: 1.5rem;
    padding-bottom: 1.5rem;
    border-bottom: 1px solid #eee;
}

.review-section:last-of-type {
    border-bottom: none;
}

.review-section__header {
    display: flex;
    justify-content: space-between;
    align-items: center;
}

.review-section__header h3 {
    margin: 0 0 0.75rem 0;
}

.review-section dl {
    display: grid;
    grid-template-columns: 120px 1fr;
    gap: 0.5rem;
    margin: 0;
}

.review-section dt {
    font-weight: 600;
    color: #555;
}

.review-section dd {
    margin: 0;
}

.review-work-entry {
    margin-bottom: 1rem;
    padding: 0.75rem;
    background: #f9f9f9;
    border-radius: 4px;
}

.review-dates {
    font-size: 0.9rem;
    color: #666;
}

.review-reference {
    margin-bottom: 0.75rem;
    padding: 0.5rem 0.75rem;
    background: #f9f9f9;
    border-radius: 4px;
}

.review-cover-letter {
    white-space: pre-wrap;
    background: #f9f9f9;
    padding: 1rem;
    border-radius: 4px;
}

/* Submission Confirmation */
.submission-confirmation {
    text-align: center;
    padding: 3rem 2rem;
}

.submission-confirmation h3 {
    color: #28a745;
    font-size: 1.5rem;
}

